(* [comment removed for export] *)
Definition acc_addr (i : instr) (c : core) : option (word * nat) :=
  match i with
  | Load sz _ _ rs1 imm => Some ((rget c rs1 + sext 64 imm)%bv, KX2.msize_bytes sz)
  | Store sz rs1 _ imm => Some ((rget c rs1 + sext 64 imm)%bv, KX2.msize_bytes sz)
  | Lr wd _ _ _ rs1 => Some (rget c rs1, match wd with AW => 4%nat | AD => 8%nat end)
  | Sc wd _ _ _ rs1 _ => Some (rget c rs1, match wd with AW => 4%nat | AD => 8%nat end)
  | Amo _ wd _ _ _ rs1 _ => Some (rget c rs1, match wd with AW => 4%nat | AD => 8%nat end)
  | FLoad fmt _ rs1 imm => Some ((rget c rs1 + sext 64 imm)%bv, match fmt with FMT_S => 4%nat | FMT_D => 8%nat end)
  | FStore fmt rs1 _ imm => Some ((rget c rs1 + sext 64 imm)%bv, match fmt with FMT_S => 4%nat | FMT_D => 8%nat end)
  | _ => None
  end.

Definition acc_ok (RNG : footprint) (i : instr) (c : core) : Prop :=
  match acc_addr i c with Some (a, n) => RNG (bv_unsigned a) n | None => True end.

(* [comment removed for export] *)
Inductive eff_acc (P : word -> nat -> Prop) : eff -> Prop :=
| EaDone : forall c, eff_acc P (EDone c)
| EaIllegal : forall c, eff_acc P (EIllegal c)
| EaDefIllegal : forall c, eff_acc P (EDefinedIllegal c)
| EaEcall : forall c, eff_acc P (EEcall c)
| EaEbreak : forall c, eff_acc P (EEbreak c)
| EaFault : forall c, eff_acc P (EFault c)
| EaLoad : forall n a k, P a (width_bytes n) -> (forall v, eff_acc P (k v)) -> eff_acc P (ELoad n a k)
| EaStore : forall n a v k, P a (width_bytes n) -> eff_acc P k -> eff_acc P (EStore n a v k).

Section WithSegs.
Variable segs : list Segment.

Lemma interp_acc : forall (RNG : footprint) t, eff_acc (fun a n => RNG (bv_unsigned a) n) t -> forall m r,
  interp_eff_accesses segs t m = MachineOk r -> Forall (acc_in RNG) (accessed_ranges _ r).
Proof.
