Local Ltac acc_struct HA :=
  repeat first
    [ apply EaDone | apply EaIllegal | apply EaDefIllegal | apply EaEcall | apply EaEbreak | apply EaFault
    | apply EaLoad; [exact HA | intros ?]
    | apply EaStore; [exact HA | ]
    | match goal with |- eff_acc _ (match ?X with _ => _ end) => destruct X end
    | match goal with |- eff_acc _ (match ?X with _ => _ end _) => destruct X end ].

Local Ltac unfold_exec :=
  cbv beta iota zeta delta [exec with_pc load_val store_val exec_csr resolve_rm frm_of].

