Lemma step_mstepF : forall RNG R F pc fc rv m ro w i,
  fetch_word segs pc = Some w -> is_ecall w = false -> decode_any w = Some (i, 4%Z) ->
  acc_ok RNG i (Core R F pc fc rv) ->
