Definition is_atomic (i : instr) : bool :=
  match i with Lr _ _ _ _ _ | Sc _ _ _ _ _ _ | Amo _ _ _ _ _ _ _ => true | _ => false end.

(* [comment removed for export] *)
Definition sacc (i : instr) (ss : sym_state) : list (saddr * nat) :=
  let fk := facts_of (s_know ss) in
  match i with
  | Load sz _ _ rs imm => [(to_saddrK fk (sr_get (s_regs ss) rs) (bv_signed imm), KX2.msize_bytes sz)]
  | Store sz rs1 _ imm => [(to_saddrK fk (sr_get (s_regs ss) rs1) (bv_signed imm), KX2.msize_bytes sz)]
  | _ => []
  end.

Section Driver.
Variable segs : list Segment.

Fixpoint kx_exec_go (fuel : nat) (first : bool) (stops : list Z) (scr : scripts) (ss : sym_state)
         (acc : list sidecond) (accs : list (saddr * nat)) : sym_state * list sidecond * scripts * list (saddr * nat) :=
  match fuel with
  | O => (ss, acc, scr, accs)
  | S f =>
    if (negb first && existsb (Z.eqb (s_pc ss)) stops)%bool then (ss, acc, scr, accs) else
    match fetch_word segs (Z_to_bv 64 (s_pc ss)) with
    | None => (ss, acc, scr, accs)
    | Some w =>
      if is_ecall w then (ss, acc, scr, accs) else
      match decode_any w with
      | None => (ss, acc, scr, accs)
      | Some (i, sz) =>
        if negb (Z.eqb sz 4) then (ss, acc, scr, accs) else
        if is_atomic i then (ss, acc, scr, accs) else
        match sym_step segs i ss scr with
        | SStop => (ss, acc, scr, accs)
        | SOk ss2 scs2 scr2 => kx_exec_go f false stops scr2 ss2 (sc_add scs2 acc) (sacc i ss ++ accs)
        end
      end
    end
  end.

Definition kx_exec (fuel : nat) (stops : list Z) (scr : scripts) (ss : sym_state) :=
  kx_exec_go fuel true stops scr ss [] [].

Definition accP (RNG : footprint) (E : env) (an : saddr * nat) : Prop := RNG (bv_unsigned (adenot E (fst an))) (snd an).

Lemma sym_step_resv : forall i ss scr ss2 scs2 scr2,
  is_atomic i = false -> sym_step segs i ss scr = SOk ss2 scs2 scr2 -> s_resv ss = None -> s_resv ss2 = None.
Proof.
