(* [comment removed for export] *)
Lemma sacc_acc_ok : forall RNG E base ss regs pc F fc rv i,
  regs_ok E (s_regs ss) regs -> know_ok segs E base (s_know ss) ->
  is_atomic i = false -> (forall sv, i <> FLoad (fst (fst sv)) (snd (fst sv)) (fst (snd sv)) (snd (snd sv))) ->
  (forall sv, i <> FStore (fst (fst sv)) (snd (fst sv)) (fst (snd sv)) (snd (snd sv))) ->
  Forall (accP RNG E) (sacc i ss) ->
