Section DriverSound.
Context {fx : AS.PropExec.FPState}.
Variable segs : list Segment.

Lemma kx_exec_go_sound : forall RNG fuel first stops scr ss acc accs E base rom,
  s_resv ss = None ->
  match kx_exec_go segs fuel first stops scr ss acc accs with
  | (r, accr, _, accsr) =>
    s_resv r = None /\
    (scs_denot segs base E accr -> scs_denot segs base E acc) /\
    (Forall (accP RNG E) accsr -> Forall (accP RNG E) accs) /\
    (forall ms, scs_denot segs base E accr -> Forall (accP RNG E) accsr -> st_okR segs E base rom ss ms ->
       exists mr, mstepsF segs RNG ms mr /\ st_okR segs E base rom r mr)
  end.
