Theorem kx_run_evtF : forall RNG fuel stops scr pc sr kn nx ss' scs scr' accs E R F fc m rom (Q : machine_state -> Prop),
  rfull R ->
  kx_exec segs fuel stops scr (SS pc sr [] kn nx) = (ss', scs, scr', accs) ->
